import logging
import tenacity
from tenacity import after_log

logging.basicConfig(level=logging.INFO, format='%(levelname)s:%(name)s:%(message)s')
logger = logging.getLogger(__name__)

print("=== Test 1: Function that always fails ===")
@tenacity.retry(
    stop=tenacity.stop_after_attempt(2),
    after=after_log(logger, logging.INFO)
)
def always_fails():
    raise ValueError("Always fails")

try:
    always_fails()
except tenacity.RetryError:
    print("Function failed after retries")

print("\n=== Test 2: Function that succeeds after one failure ===")
attempt_count = 0

@tenacity.retry(
    stop=tenacity.stop_after_attempt(3),
    after=after_log(logger, logging.INFO)
)
def fails_then_succeeds():
    global attempt_count
    attempt_count += 1
    if attempt_count <= 2:
        raise ValueError(f"Attempt {attempt_count} fails")
    return f"Success on attempt {attempt_count}!"

try:
    result = fails_then_succeeds()
    print(f"Function succeeded: {result}")
except tenacity.RetryError:
    print("Function failed after retries")
