cat <<'EOF' > test_comprehensive.py
from tenacity import TornadoRetrying, stop_after_attempt, wait_fixed
from tornado import gen
import tornado.ioloop

# Test 1: Simple success case
@gen.coroutine
def success_function():
    print("Function called successfully")
    raise gen.Return("success")

# Test 2: Function that fails then succeeds
call_count = 0
@gen.coroutine
def retry_function():
    global call_count
    call_count += 1
    print(f"Attempt {call_count}")
    if call_count < 3:
        raise Exception(f"Attempt {call_count} failed")
    raise gen.Return("success after retries")

@gen.coroutine
def run_tests():
    print("=== Test 1: Simple success ===")
    retrying1 = TornadoRetrying(stop=stop_after_attempt(3))
    try:
        result1 = yield retrying1(success_function)
        print("Result:", result1)
    except Exception as e:
        print("Error:", e)

    print("\n=== Test 2: Retry scenario ===")
    retrying2 = TornadoRetrying(stop=stop_after_attempt(5), wait=wait_fixed(0.1))
    try:
        result2 = yield retrying2(retry_function)
        print("Result:", result2)
    except Exception as e:
        print("Error:", e)

if __name__ == "__main__":
    tornado.ioloop.IOLoop.current().run_sync(run_tests)
EOF

